{
  "html": "<figure class="product-media" aria-label="Product Image"><img src="assets/photos/pottery.jpg" alt="물레 위 흙을 손으로 빚는 도자기 작업"></figure>",
  "css": ".product-media {
  margin: 0;
  width: 100%;
}

.product-media img {
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  object-position: 44% center;
  border-radius: 0;
}

@media (min-width: 701px) {
  .product-media img {
    border-radius: 8px;
  }
}"
}
